from scrapy.commands import ScrapyCommand
from scrapy.exceptions import UsageError
from scrapy.utils.template import render_templatefile
from scrapy.utils.python import to_unicode
from scrapy.utils.conf import get_project_settings
from scrapy.utils.project import inside_project
from scrapy.utils.url import is_valid_url, normalize_url  # Updated import

class Command(ScrapyCommand):

    requires_project = False
    default_settings = {'LOG_ENABLED': False}

    def syntax(self):
        return "<name> <domain>"

    def short_desc(self):
        return "Generate new spider using pre-defined templates"

    def add_options(self, parser):
        ScrapyCommand.add_options(self, parser)
        parser.add_option("-t", "--template", metavar="TEMPLATE",
                          help="uses a custom template.")
        parser.add_option("-l", "--list", action="store_true",
                          help="list available templates")

    def run(self, args, opts):
        if opts.list:
            self._list_templates()
            return
        if len(args) not in (1, 2):
            raise UsageError()
        name = args[0]
        try:
            domain = args[1]
        except IndexError:
            domain = None

        if domain and not is_valid_url(domain):
            raise UsageError(f"Invalid domain: {domain}")

        if domain:
            domain = normalize_url(domain)

        if inside_project():
            spiders_dir = self.crawler_process.spider_loader.spiders_module.encode('utf-8')
            spiders_dir = spiders_dir.rsplit(b'.', 1)[0].replace(b'.', b'/')
        else:
            spiders_dir = 'spiders'

        template_name = opts.template if opts.template else 'basic'
        template_file = self._find_template(template_name)
        rendered_template = render_templatefile(template_file, **{
            'project_name': to_unicode(self.crawler_process.settings.get('BOT_NAME')),
            'spider_name': to_unicode(name),
            'domain': to_unicode(domain),
        })
        filename = f"{spiders_dir}/{name}.py"
        with open(filename, 'w') as f:
            f.write(rendered_template)
        self.exitmsg(f"Created spider {name!r} using template {template_name!r} in module:\n  {filename}")

    def _find_template(self, template):
        template_file = f"{self.templates_dir}/{template}.tmpl"
        if not exists(template_file):
            raise UsageError(f"Unknown template: {template}")
        return template_file

    def _list_templates(self):
        print("Available templates:")
        for template in self._list_files(self.templates_dir):
            print(f"  {template}")

    @property
    def templates_dir(self):
        return join(dirname(__file__), '..', '..', 'templates', 'spiders')

    def _list_files(self, dir, ext=None):
        for name in sorted(listdir(dir)):
            if ext is None or name.endswith(ext):
                yield name
